import React from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation
} from 'react-router-dom';
import useAuth from './hooks/useAuth'; // IMPORTAR EL HOOK DE AUTENTICACIÓN

// IMPORTAR COMPONENTES DE VISTAS
import LoginRegister from './componentes/LoginRegister';
import BookCatalog from './componentes/BookCatalog'; // VISTA DE ESTUDIANTE
import BookRegistration from './componentes/BookRegistration'; // VISTA DE ADMINISTRADOR

// NOTA: Asegúrate de importar tus estilos aquí si son necesarios globalmente


// ----------------------------------------------------------------
// COMPONENTE DE PROTECCIÓN DE RUTA (AuthWrapper)
// ----------------------------------------------------------------
const AuthWrapper = ({ children, allowedRoles }) => {
  // Obtenemos el estado de usuario del hook
  const { user, isLoading, logout } = useAuth();
  const location = useLocation();

  // Puedes agregar una pantalla de carga mientras se verifica el token inicial
  if (isLoading === null) {
    return <div>Cargando sesión...</div>;
  }

  // 1. Si no hay usuario (No autenticado), redirige al login
  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // 2. Si hay usuario, verifica el rol
  if (allowedRoles && !allowedRoles.includes(user.rol)) {
    // Lógica: Si intenta ir a una ruta que no le corresponde, lo enviamos a la suya por defecto
    if (user.rol === 'Estudiante') {
      return <Navigate to="/catalogo" replace />;
    }
    if (user.rol === 'Administrador') {
      return <Navigate to="/registro" replace />;
    }

    // Si el rol no está mapeado, por seguridad cerramos sesión y vamos al login
    logout();
    return <Navigate to="/login" replace />;
  }

  // 3. Autenticado y Rol Correcto: Renderiza el componente solicitado
  return children;
};

// ----------------------------------------------------------------
// LÓGICA DE REDIRECCIÓN INICIAL (Ruta /)
// ----------------------------------------------------------------
const LoginRedirect = () => {
  const { user } = useAuth();

  // Si ya está logueado, redirige según el rol. Si no, va a /login.
  if (user) {
    return user.rol === 'Estudiante'
      ? <Navigate to="/catalogo" replace />
      : <Navigate to="/registro" replace />;
  }

  // Si no está logueado, lo envía al formulario de autenticación
  return <Navigate to="/login" replace />;
};


// ----------------------------------------------------------------
// COMPONENTE PRINCIPAL APP
// ----------------------------------------------------------------
function App() {
  return (
    <Router>
      <div className="App">
        <Routes>

          {/* 1. Ruta de Autenticación Pública */}
          <Route path="/login" element={<LoginRegister />} />

          {/* 2. Ruta de Estudiante (Protegida) */}
          <Route
            path="/catalogo"
            element={
              <AuthWrapper allowedRoles={['Estudiante']}>
                <BookCatalog />
              </AuthWrapper>
            }
          />

          {/* 3. Ruta de Administrador (Protegida) */}
          <Route
            path="/registro"
            element={
              <AuthWrapper allowedRoles={['Administrador']}>
                <BookRegistration />
              </AuthWrapper>
            }
          />

          {/* 4. Ruta Raíz: Redirección inicial */}
          <Route path="/" element={<LoginRedirect />} />

          {/* 5. Ruta de Fallback (404) */}
          <Route path="*" element={<div>404: Página no encontrada</div>} />

        </Routes>
      </div>
    </Router>
  );
}

export default App;
